import { PanelPlugin } from '@grafana/data';
import { SimplePanel } from './components/SimplePanel';
import { CaptureButtonEditor } from './components/CaptureButtonEditor';
import { PopsEditor } from './components/PopsEditor';
import { RoutesEditor } from './components/RoutesEditor';
import { PanelOptions } from './types';

export const plugin = new PanelPlugin<PanelOptions>(SimplePanel).setPanelOptions((builder) => {
  builder.addRadio({
    path: 'viewMode',
    name: 'Exibição inicial',
    description: 'Mapa geográfico ou topologia com posições independentes.',
    category: ['Visualização'],
    defaultValue: 'map',
    settings: {
      options: [
        { label: 'Mapa', value: 'map' },
        { label: 'Topologia', value: 'topology' },
      ],
    },
  });
  builder.addCustomEditor({
    id: 'routes',
    path: 'routes',
    name: 'Rotas',
    description: 'Gerenciamento de rotas',
    category: ['Cadastro de Rotas'],
    editor: RoutesEditor,
    defaultValue: [],
  });

  builder.addSelect({
    path: 'mapLabelMode',
    name: 'Rótulos dos POPs',
    description: 'Inteligente evita sobreposição. Os detalhes continuam disponíveis ao selecionar o POP.',
    category: ['Visualização'],
    defaultValue: 'smart',
    settings: {
      options: [
        { label: 'Inteligente (sem sobreposição)', value: 'smart' },
        { label: 'Somente nome', value: 'name' },
        { label: 'Nome, equipamentos e status', value: 'details' },
        { label: 'Ao passar o mouse', value: 'hover' },
      ],
    },
  });
  builder.addRadio({
    path: 'mapTone',
    name: 'Contraste do fundo',
    description: 'Suave reduz o destaque das ruas e cidades para priorizar a rede.',
    category: ['Visualização'],
    defaultValue: 'muted',
    settings: {
      options: [
        { label: 'Suave', value: 'muted' },
        { label: 'Original', value: 'original' },
      ],
    },
  });
  builder.addSelect({
    path: 'topologyRouteStyle',
    name: 'Traçado na topologia',
    description: 'Aplica-se a ligações sem desvios manuais. O caminho geográfico permanece independente.',
    category: ['Visualização'],
    defaultValue: 'curve',
    settings: {
      options: [
        { label: 'Curvas suaves', value: 'curve' },
        { label: 'Direto', value: 'direct' },
        { label: 'Ortogonal', value: 'orthogonal' },
      ],
    },
  });

  builder.addCustomEditor({
    id: 'pops',
    path: 'pops',
    name: 'POPs',
    description: 'Gerenciamento de POPs',
    category: ['Cadastro de POP'],
    editor: PopsEditor,
    defaultValue: [],
  });

  builder.addSelect({
    path: 'mapProvider',
    name: 'Provedor de mapa',
    description: 'Escolha o provedor de tiles do mapa',
    category: ['Configuracao de Mapa'],
    settings: {
      options: [
        { label: 'OpenStreetMap', value: 'osm' },
        { label: 'OpenStreetMap HOT', value: 'osm_hot' },
        { label: 'CartoDB Light', value: 'carto_light' },
        { label: 'CartoDB Dark', value: 'carto_dark' },
        { label: 'CartoDB Voyager', value: 'carto_voyager' },
        { label: 'Google Roadmap', value: 'google_roadmap' },
        { label: 'Google Satellite', value: 'google_satellite' },
        { label: 'Google Hybrid', value: 'google_hybrid' },
        { label: 'Google Terrain', value: 'google_terrain' },
      ],
    },
    defaultValue: 'osm',
  });

  builder.addNumberInput({
    path: 'centerLat',
    name: 'Latitude central',
    description: 'Latitude do centro inicial do mapa',
    category: ['Configuracao de Mapa'],
    defaultValue: -23.5505,
    settings: {
      step: 0.000001,
    },
  });

  builder.addNumberInput({
    path: 'centerLng',
    name: 'Longitude central',
    description: 'Longitude do centro inicial do mapa',
    category: ['Configuracao de Mapa'],
    defaultValue: -46.6333,
    settings: {
      step: 0.000001,
    },
  });

  builder.addNumberInput({
    path: 'zoom',
    name: 'Zoom inicial',
    description: 'Nivel de zoom inicial do mapa (1-20)',
    category: ['Configuracao de Mapa'],
    defaultValue: 12,
    settings: {
      min: 1,
      max: 20,
    },
  });

  builder.addCustomEditor({
    id: 'captureNow',
    path: 'captureNow',
    name: 'Capturar do mapa atual',
    description: 'Captura as coordenadas e zoom do mapa atual no painel',
    category: ['Configuracao de Mapa'],
    editor: CaptureButtonEditor,
    defaultValue: false,
  });

  builder.addSelect({
    path: 'transportLineAnimation',
    name: 'Animacao das linhas',
    description: 'Escolha como as linhas de transporte devem se comportar no mapa',
    category: ['Configuracao de Mapa'],
    settings: {
      options: [
        { label: 'Fluxo direcional', value: 'flow' },
        { label: 'Linha estatica', value: 'static' },
      ],
    },
    defaultValue: 'flow',
  });

  builder.addNumberInput({
    path: 'transportLineWeight',
    name: 'Espessura da linha',
    description: 'Espessura das linhas de transporte (1-10)',
    category: ['Configuracao de Mapa'],
    settings: {
      min: 1,
      max: 10,
      step: 1,
    },
    defaultValue: 4,
  });

  builder.addNumberInput({
    path: 'transportAnimationSpeed',
    name: 'Velocidade da animacao',
    description: 'Velocidade da animacao das linhas (1-10, menor = mais rapido)',
    category: ['Configuracao de Mapa'],
    settings: {
      min: 1,
      max: 10,
      step: 1,
    },
    defaultValue: 5,
  });

  return builder;
});
